mapper.select:
SELECT o.id, o.code, o.customer_id, o.customer_name, o.phone, o.total, o.status, o.ordered_at, o.delivered_at, o.note, o.source, o.tg_chat_id, o.created_at, o.updated_at, (SELECT string_agg(i.product_name || ' ×' || i.qty, ', ') FROM sales_order_item i WHERE i.order_id = o.id) AS items_summary FROM sales_order o
AND o.status = #{status}
ORDER BY o.ordered_at DESC, o.id DESC LIMIT #{size} OFFSET #{offset}

SELECT id, code, customer_id, customer_name, phone, total, status,
       ordered_at, delivered_at, note, source, tg_chat_id, created_at, updated_at
FROM sales_order WHERE id = #{id}

mapper.update:
UPDATE sales_order
SET status = 'delivered', delivered_at = CURRENT_DATE, updated_at = now()
WHERE id = #{id}
